    20  void UA_Node_deleteMembers(UA_Node *node) {
    21      /* Delete standard content */
    22      UA_NodeId_deleteMembers(&node->nodeId);
    23      UA_QualifiedName_deleteMembers(&node->browseName);
    24      UA_LocalizedText_deleteMembers(&node->displayName);
    25      UA_LocalizedText_deleteMembers(&node->description);
    26
    27      /* Delete references */
    28      UA_Node_deleteReferences(node);
    29
    30      /* Delete unique content of the nodeclass */
    31      switch(node->nodeClass) {
    32      case UA_NODECLASS_OBJECT:
    33          break;
    34      case UA_NODECLASS_METHOD:
    35          break;
    36      case UA_NODECLASS_OBJECTTYPE:
    37          break;
    38      case UA_NODECLASS_VARIABLE:
    39      case UA_NODECLASS_VARIABLETYPE: {
    40          UA_VariableNode *p = (UA_VariableNode*)node;
    41          UA_NodeId_deleteMembers(&p->dataType);
    42          UA_Array_delete(p->arrayDimensions, p->arrayDimensionsSize,
    43                          &UA_TYPES[UA_TYPES_INT32]);
    44          p->arrayDimensions = NULL;
    45          p->arrayDimensionsSize = 0;
    46          if(p->valueSource == UA_VALUESOURCE_DATA)
    47              UA_DataValue_deleteMembers(&p->value.data.value);
    48          break;
    49      }
    50      case UA_NODECLASS_REFERENCETYPE: {
    51          UA_ReferenceTypeNode *p = (UA_ReferenceTypeNode*)node;
    52          UA_LocalizedText_deleteMembers(&p->inverseName);
    53          break;
    54      }
    55      case UA_NODECLASS_DATATYPE:
    56          break;
    57      case UA_NODECLASS_VIEW:
    58          break;
    59      default:
    60          break;
    61      }
    62  }
