    71  UA_CommonVariableNode_copy(const UA_VariableNode *src, UA_VariableNode *dst) {
    72      UA_StatusCode retval = UA_Array_copy(src->arrayDimensions,
    73                                           src->arrayDimensionsSize,
    74                                           (void**)&dst->arrayDimensions,
    75                                           &UA_TYPES[UA_TYPES_INT32]);
    76      if(retval != UA_STATUSCODE_GOOD)
    77          return retval;
    78      dst->arrayDimensionsSize = src->arrayDimensionsSize;
    79      retval = UA_NodeId_copy(&src->dataType, &dst->dataType);
    80      dst->valueRank = src->valueRank;
    81      dst->valueSource = src->valueSource;
    82      if(src->valueSource == UA_VALUESOURCE_DATA) {
    83          retval |= UA_DataValue_copy(&src->value.data.value,
    84                                      &dst->value.data.value);
    85          dst->value.data.callback = src->value.data.callback;
    86      } else
    87          dst->value.dataSource = src->value.dataSource;
    88      return retval;
    89  }
