   231  UA_Node_copy_alloc(const UA_Node *src) {
   232      // use dstPtr to trick static code analysis in accepting dirty cast
   233      void *dstPtr;
   234      switch(src->nodeClass) {
   235          case UA_NODECLASS_OBJECT:
   236              dstPtr = UA_malloc(sizeof(UA_ObjectNode));
   237              break;
   238          case UA_NODECLASS_VARIABLE:
   239              dstPtr =UA_malloc(sizeof(UA_VariableNode));
   240              break;
   241          case UA_NODECLASS_METHOD:
   242              dstPtr = UA_malloc(sizeof(UA_MethodNode));
   243              break;
   244          case UA_NODECLASS_OBJECTTYPE:
   245              dstPtr = UA_malloc(sizeof(UA_ObjectTypeNode));
   246              break;
   247          case UA_NODECLASS_VARIABLETYPE:
   248              dstPtr = UA_malloc(sizeof(UA_VariableTypeNode));
   249              break;
   250          case UA_NODECLASS_REFERENCETYPE:
   251              dstPtr = UA_malloc(sizeof(UA_ReferenceTypeNode));
   252              break;
   253          case UA_NODECLASS_DATATYPE:
   254              dstPtr = UA_malloc(sizeof(UA_DataTypeNode));
   255              break;
   256          case UA_NODECLASS_VIEW:
   257              dstPtr = UA_malloc(sizeof(UA_ViewNode));
   258              break;
   259          default:
   260              return NULL;
   250          UA_DataValue_init(&vt_value);
   251          retval = readValueAttribute(server, session,
   252                                      (const UA_VariableNode*)vt, &vt_value);
   253          if(retval == UA_STATUSCODE_GOOD && vt_value.hasValue) {
   254              retval = UA_Variant_copy(&vt_value.value, &node->value.data.value.value);
   255              node->value.data.value.hasValue = true;
   256          }
   257          UA_DataValue_deleteMembers(&vt_value);
   258      }
   259
   260      /* If no datatype is given, use the datatype of the vt */
   261      if(retval == UA_STATUSCODE_GOOD && UA_NodeId_isNull(&node->dataType)) {
   262          UA_LOG_INFO_SESSION(server->config.logger, session, "AddNodes: "
   263                              "No datatype given; Copy the datatype attribute "
   264                              "from the TypeDefinition");
   265          retval = UA_NodeId_copy(&vt->dataType, &node->dataType);
   266      }
   267
   268      /* TODO: If the vt has arraydimensions but this variable does not, copy */
   269
   270      UA_Nodestore_release(server, (const UA_Node*)vt);
   271      return retval;
   272  }
