   274  /* Search for an instance of "browseName" in node searchInstance. Used during
   275   * copyChildNodes to find overwritable/mergable nodes. Does not touch
   276   * outInstanceNodeId if no child is found. */
   277  static UA_StatusCode
   278  findChildByBrowsename(UA_Server *server, UA_Session *session,
   279                        const UA_NodeId *searchInstance,
   280                        const UA_QualifiedName *browseName,
   281                        UA_NodeId *outInstanceNodeId) {
   282      UA_BrowseDescription bd;
   283      UA_BrowseDescription_init(&bd);
   284      bd.nodeId = *searchInstance;
   285      bd.referenceTypeId = UA_NODEID_NUMERIC(0, UA_NS0ID_AGGREGATES);
   286      bd.includeSubtypes = true;
   287      bd.browseDirection = UA_BROWSEDIRECTION_FORWARD;
   288      bd.nodeClassMask = UA_NODECLASS_OBJECT | UA_NODECLASS_VARIABLE | UA_NODECLASS_METHOD;
   289      bd.resultMask = UA_BROWSERESULTMASK_NODECLASS | UA_BROWSERESULTMASK_BROWSENAME;
   290
   291      UA_BrowseResult br;
   292      UA_BrowseResult_init(&br);
   293      UA_UInt32 maxrefs = 0;
   294      Operation_Browse(server, session, &maxrefs, &bd, &br);
   295      if(br.statusCode != UA_STATUSCODE_GOOD)
   296          return br.statusCode;
   297
   298      UA_StatusCode retval = UA_STATUSCODE_GOOD;
   299      for(size_t i = 0; i < br.referencesSize; ++i) {
   300          UA_ReferenceDescription *rd = &br.references[i];
   301          if(rd->browseName.namespaceIndex == browseName->namespaceIndex &&
   302             UA_String_equal(&rd->browseName.name, &browseName->name)) {
   303              retval = UA_NodeId_copy(&rd->nodeId.nodeId, outInstanceNodeId);
   304              break;
   305          }
   306      }
   307
   308      UA_BrowseResult_deleteMembers(&br);
   309      return retval;
   310  }
