   312  static const UA_NodeId mandatoryId =
   313      {0, UA_NODEIDTYPE_NUMERIC, {UA_NS0ID_MODELLINGRULE_MANDATORY}};
   314  static const UA_NodeId hasModellingRuleId =
   315      {0, UA_NODEIDTYPE_NUMERIC, {UA_NS0ID_HASMODELLINGRULE}};
   316
   317  static UA_Boolean
   318  isMandatoryChild(UA_Server *server, UA_Session *session,
   319                   const UA_NodeId *childNodeId) {
   320      /* Get the child */
   321      const UA_Node *child = UA_Nodestore_get(server, childNodeId);
   322      if(!child)
   323          return false;
   324
   325      /* Look for the reference making the child mandatory */
   326      for(size_t i = 0; i < child->referencesSize; ++i) {
   327          UA_NodeReferenceKind *refs = &child->references[i];
   328          if(!UA_NodeId_equal(&hasModellingRuleId, &refs->referenceTypeId))
   329              continue;
   330          if(refs->isInverse)
   331              continue;
   332          for(size_t j = 0; j < refs->targetIdsSize; ++j) {
   333              if(UA_NodeId_equal(&mandatoryId, &refs->targetIds[j].nodeId)) {
   334                  UA_Nodestore_release(server, child);
   335                  return true;
   336              }
   337          }
   338      }
   339
   340      UA_Nodestore_release(server, child);
   341      return false;
   342  }
