   354  /*
   355   * This method only deletes references from the node which are not matching any type in the given array.
   356   * Could be used to e.g. delete all the references, except 'HASMODELINGRULE'
   357   */
   358  static void deleteReferencesSubset(UA_Node *node, size_t referencesSkipSize, UA_NodeId* referencesSkip) {
   359      if(referencesSkipSize == 0) {
   360          UA_Node_deleteReferences(node);
   361          return;
   362      }
   363
   364      /* Let's count if there are references left. If not just delete all the references.
   365       * It's faster */
   366      size_t newSize = 0;
   367      for(size_t i = 0; i < node->referencesSize; ++i) {
   368          for(size_t j = 0; j < referencesSkipSize; j++) {
   369              if(UA_NodeId_equal(&node->references[i].referenceTypeId, &referencesSkip[j])) {
   370                  newSize++;
   371              }
   372          }
   373      }
   374      if(newSize == 0) {
   375          UA_Node_deleteReferences(node);
   376          return;
   377      }
   378
   379      /* Now copy the remaining references to a new array */
   380      UA_NodeReferenceKind *newReferences = (UA_NodeReferenceKind *)UA_malloc(sizeof(UA_NodeReferenceKind) * (newSize));
   381      size_t curr = 0;
   382      UA_StatusCode retval = UA_STATUSCODE_GOOD;
   383      for(size_t i = 0; i < node->referencesSize && retval == UA_STATUSCODE_GOOD; ++i) {
   384          for(size_t j = 0; j < referencesSkipSize; j++) {
   385              if(!UA_NodeId_equal(&node->references[i].referenceTypeId, &referencesSkip[j]))
   386                  continue;
   387
   388              // copy the reference
   389              UA_NodeReferenceKind *srefs = &node->references[i];
   390              UA_NodeReferenceKind *drefs = &newReferences[curr++];
   391              drefs->isInverse = srefs->isInverse;
   392              retval = UA_NodeId_copy(&srefs->referenceTypeId, &drefs->referenceTypeId);
   393              if(retval != UA_STATUSCODE_GOOD)
   394                  break;
   395              retval = UA_Array_copy(srefs->targetIds, srefs->targetIdsSize,
   396                                     (void**)&drefs->targetIds,
   397                                     &UA_TYPES[UA_TYPES_EXPANDEDNODEID]);
   398              if(retval != UA_STATUSCODE_GOOD)
   399                  break;
   400              drefs->targetIdsSize = srefs->targetIdsSize;
   401              break;
   402          }
   403          if(retval != UA_STATUSCODE_GOOD) {
   404              for(size_t k=0; k<i; k++) {
   405                  UA_NodeReferenceKind *refs = &newReferences[i];
   406                  for(size_t j = 0; j < refs->targetIdsSize; ++j)
   407                      UA_ExpandedNodeId_deleteMembers(&refs->targetIds[j]);
   408                  UA_Array_delete(refs->targetIds, refs->targetIdsSize, &UA_TYPES[UA_TYPES_EXPANDEDNODEID]);
   409                  UA_NodeId_deleteMembers(&refs->referenceTypeId);
   410              }
   411          }
   412      }
   413
   414      UA_Node_deleteReferences(node);
   415      if(retval == UA_STATUSCODE_GOOD) {
   416          node->references = newReferences;
   417          node->referencesSize = newSize;
   418      } else {
   419          UA_free(newReferences);
   420      }
   421  }
