   428  static UA_StatusCode
   429  copyChildNode(UA_Server *server, UA_Session *session,
   430                const UA_NodeId *destinationNodeId,
   431                const UA_ReferenceDescription *rd) {
   432      UA_NodeId existingChild = UA_NODEID_NULL;
   433      UA_StatusCode retval =
   434          findChildByBrowsename(server, session, destinationNodeId,
   435                                &rd->browseName, &existingChild);
   436      if(retval != UA_STATUSCODE_GOOD)
   437          return retval;
   438
   439      /* Have a child with that browseName. Try to deep-copy missing members. */
   440      if(!UA_NodeId_isNull(&existingChild)) {
   441          if(rd->nodeClass == UA_NODECLASS_VARIABLE ||
   442             rd->nodeClass == UA_NODECLASS_OBJECT)
   443              retval = copyChildNodes(server, session, &rd->nodeId.nodeId, &existingChild);
   444          UA_NodeId_deleteMembers(&existingChild);
   445          return retval;
   446      }
   447
   448      /* Is the child mandatory? If not, skip */
   449      if(!isMandatoryChild(server, session, &rd->nodeId.nodeId))
   450          return UA_STATUSCODE_GOOD;
